/** How themes are grouped in the style picker, in display order. */
enum class StyleGroup(val title: String) {
    BRIGHT("Bright"),
    PALETTE("Classic palettes"),
    ORIGINAL("Originals"),
    WALLPAPER("Match my wallpaper"),
    PHOTO("Your photo"),
}

